input.new_string:
.ac-live-hero__orb {
  --ac-live-accent: #ffd54a;
  flex: 0 0 auto;
  width: 3.6rem;
  height: 3.6rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.55rem;
  color: var(--ac-live-accent);
  background:
    radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.25), transparent 45%),
    radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.08), rgba(0, 0, 0, 0.4));
  border: 1px solid var(--ac-live-accent);
  box-shadow: 0 0 28px var(--ac-live-accent);
  animation: ac-live-orb 2.4s ease-in-out infinite;
}

